def IsNumeric(value: Any) -> object {
    if not isinstance(value, str) {
        raise Exception('value must be a string.');
    }
    try {
        valtxt = value;
        value = int(valtxt);
        value = float(valtxt);
        return True;
    } except Exception as e {
        return False;
    }
